    reduced.swipe.pointermove(pointer('pointermove', -30, 10));
    reduced.swipe.pointerup(pointer('pointerup', -30, 10));
    expect(reduced.commit).toHaveBeenCalledTimes(1);
    expect(reduced.swipe.offset.value).toBe(0);
  });
