1	// @vitest-environment node
2	import { afterAll, beforeAll, describe, expect, it } from 'vitest';
3	import { PHONE_VIEWPORT, startRenderedHarness, type RenderedHarness } from '../rendered/chromium';
4	
5	const chromePath = process.env.EMAIL_OS_RENDERED_LAYOUT_CHROME ?? '';
6	const workspaceApp = '.workspace-panel:not([inert]) .app';
7	const pageRoot = new URL('../..', import.meta.url).pathname;
8	/**
9	 * The browser preview's primary workspace: conv-01..conv-18 plus the six
10	 * ADR 0006 HTML samples (conv-19..conv-24), which are the newest and so sit
11	 * above conv-01 in the list.
12	 */
13	const LOADED_CONVERSATIONS = 24;
14	
15	describe.skipIf(!chromePath)('compact conversation rows (real Chromium)', () => {
16	  let harness: RenderedHarness | null = null;
17	
18	  beforeAll(async () => {
19	    harness = await startRenderedHarness(chromePath, 'email-os-mobile-list-', pageRoot, PHONE_VIEWPORT);
20	    await harness.cdp.js('new Promise(resolve => setTimeout(resolve, 250))');
21	  }, 120_000);
22	
23	  afterAll(async () => {
24	    await harness?.close();
25	  });
26	
27	  async function touch(type: 'touchStart' | 'touchMove' | 'touchEnd', x?: number, y?: number): Promise<void> {
28	    await harness!.cdp.cmd('Input.dispatchTouchEvent', {
29	      type,
30	      touchPoints: type === 'touchEnd' ? [] : [{ x, y, id: 1, radiusX: 1, radiusY: 1, force: 1 }],
31	    });
32	  }
33	
34	  async function swipeRow(selector: string, deltaX: number, deltaY = 0): Promise<void> {
35	    const start = await harness!.cdp.js<{ x: number; y: number }>(`(() => {
36	      const row = document.querySelector(${JSON.stringify(workspaceApp)}).querySelector(${JSON.stringify(selector)});
37	      const rect = row.getBoundingClientRect();
38	      return { x: rect.left + rect.width / 2, y: rect.top + Math.min(28, rect.height / 2) };
39	    })()`);
40	    await touch('touchStart', start.x, start.y);
41	    await touch('touchMove', start.x + deltaX * 0.35, start.y + deltaY * 0.35);
42	    await touch('touchMove', start.x + deltaX * 0.7, start.y + deltaY * 0.7);
43	    await touch('touchMove', start.x + deltaX, start.y + deltaY);
44	    await touch('touchEnd');
45	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 300))');
46	  }
47	
48	  async function waitForLoadedRows(): Promise<void> {
49	    await expect.poll(() => harness!.cdp.js<number>(
50	      `document.querySelector(${JSON.stringify(workspaceApp)})?.querySelectorAll('.inbox-row').length ?? 0`,
51	    ), { timeout: 5_000 }).toBe(LOADED_CONVERSATIONS);
52	  }
53	
54	  /**
55	   * Conversation ids of the top rows, in list order. The touch tests drive
56	   * these rows by position rather than by a fixed id: a row further down can
57	   * sit under the bottom navigation, where a touch reaches the navigation
58	   * instead of the row. Each returned row must own the points the touch
59	   * helpers press, so a covered row fails here with its id, not later.
60	   */
61	  async function topRowIds(count: number): Promise<string[]> {
62	    const rows = await harness!.cdp.js<Array<{ id: string; touchable: boolean }>>(`(() => {
63	      const app = document.querySelector(${JSON.stringify(workspaceApp)});
64	      return [...app.querySelectorAll('.inbox-row')].slice(0, ${count}).map(row => {
65	        const rect = row.getBoundingClientRect();
66	        const points = [
67	          [rect.left + rect.width / 2, rect.top + Math.min(28, rect.height / 2)],
68	          [rect.left + 30, rect.top + 20],
69	        ];
70	        return {
71	          id: row.dataset.test.replace('conversation-row-', ''),
72	          touchable: points.every(([x, y]) => row.contains(document.elementFromPoint(x, y))),
73	        };
74	      });
75	    })()`);
76	    expect(rows).toHaveLength(count);
77	    for (const row of rows) expect(row, `row ${row.id} is covered`).toMatchObject({ touchable: true });
78	    return rows.map(row => row.id);
79	  }
80	
81	  it.each([
82	    { width: 412, height: 915 },
83	    { width: 360, height: 800 },
84	  ])('stacks rows without overflow at $width × $height and opens on tap', async ({ width, height }) => {
85	    await harness!.cdp.cmd('Emulation.setDeviceMetricsOverride', {
86	      width,
87	      height,
88	      screenWidth: width,
89	      screenHeight: height,
90	      deviceScaleFactor: PHONE_VIEWPORT.deviceScaleFactor,

255	  });
256	
257	  it('swipes to Mark done and Undo, opens Remind, and preserves vertical scrolling', async () => {
258	    await harness!.cdp.cmd('Emulation.setDeviceMetricsOverride', {
259	      width: 412,
260	      height: 915,
261	      screenWidth: 412,
262	      screenHeight: 915,
263	      deviceScaleFactor: PHONE_VIEWPORT.deviceScaleFactor,
264	      mobile: true,
265	    });
266	    await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="mobile-mail"]').click()`);
267	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 150))');
268	    await waitForLoadedRows();
269	    const [firstId, secondId] = await topRowIds(2);
270	
271	    const first = await harness!.cdp.js<{ left: number; width: number }>(`(() => {
272	      const row = document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="conversation-row-${firstId}"]');
273	      const rect = row.getBoundingClientRect();
274	      return { left: rect.left, width: rect.width };
275	    })()`);
276	    await swipeRow(`[data-test="conversation-row-${firstId}"]`, -80);
277	    expect(await harness!.cdp.js(`!!document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="conversation-row-${firstId}"]')`)).toBe(true);
278	    expect(await harness!.cdp.js(`!!document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="action-notice-undo"]')`)).toBe(false);
279	
280	    await swipeRow(`[data-test="conversation-row-${firstId}"]`, -first.width * 0.6);
281	    expect(await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="conversation-row-${firstId}"]') === null`)).toBe(true);
282	    expect(await harness!.cdp.js(`!!document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="action-notice"]')`)).toBe(true);
283	    await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="action-notice-undo"]').click()`);
284	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 300))');
285	    expect(await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="conversation-row-${firstId}"]') !== null`)).toBe(true);
286	
287	    await swipeRow(`[data-test="conversation-row-${firstId}"]`, 150);
288	    expect(await harness!.cdp.js(`document.querySelector('[data-reminder-picker]') !== null`)).toBe(true);
289	
290	    await harness!.cdp.js('window.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true, cancelable: true }))');
291	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 200))');
292	    const before = await harness!.cdp.js<number>(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('.inbox-scroll').scrollTop`);
293	    await swipeRow(`[data-test="conversation-row-${secondId}"]`, 4, -110);
294	    const after = await harness!.cdp.js<number>(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('.inbox-scroll').scrollTop`);
295	    expect(after).toBeGreaterThan(before);
296	    // One long real-browser flow (four swipes, Undo, Remind); the 5 s default left no
297	    // margin on a loaded machine.
298	  }, 30_000);
299	
300	  it('stacks the notice above selection with the selection pill directly over navigation', async () => {
301	    await harness!.cdp.cmd('Emulation.setDeviceMetricsOverride', {
302	      width: 412,
303	      height: 915,
304	      screenWidth: 412,
305	      screenHeight: 915,
306	      deviceScaleFactor: PHONE_VIEWPORT.deviceScaleFactor,
307	      mobile: true,
308	    });
309	    await harness!.cdp.cmd('Page.navigate', { url: harness!.appUrl });
310	    await waitForLoadedRows();
311	    await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="mobile-mail"]').click()`);
312	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 150))');
313	    await waitForLoadedRows();
314	    const [firstId, secondId, thirdId] = await topRowIds(3);
315	
316	    await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="row-select-${firstId}"]').click()`);
317	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 150))');
318	    const secondRowWidth = await harness!.cdp.js<number>(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="conversation-row-${secondId}"]').getBoundingClientRect().width`);
319	    await swipeRow(`[data-test="conversation-row-${secondId}"]`, -secondRowWidth * 0.6);
320	    expect(await harness!.cdp.js(`!!document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="conversation-row-${secondId}"]')`)).toBe(true);
321	    await harness!.cdp.js(`document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="selection-clear"]').click()`);
322	    await swipeRow(`[data-test="conversation-row-${secondId}"]`, -secondRowWidth * 0.6);
323	    expect(await harness!.cdp.js(`!!document.querySelector(${JSON.stringify(workspaceApp)}).querySelector('[data-test="action-notice-undo"]')`)).toBe(true);
324	
325	    await harness!.cdp.js(`(() => {
326	      const app = document.querySelector(${JSON.stringify(workspaceApp)});
327	      app.querySelector('[data-test="row-select-${firstId}"]').click();
328	      app.querySelector('[data-test="row-select-${thirdId}"]').click();
329	    })()`);
330	    await harness!.cdp.js('new Promise(resolve => setTimeout(resolve, 150))');
331	
332	    const geometry = await harness!.cdp.js<{
333	      selectionCount: string;
334	      notice: { top: number; bottom: number; left: number; right: number };

